// NOTIFY-002 routing brain (ADR-044): domain + severity -> Apprise {tag, type, title, body}.
// Minimalist multi-channel routing with smart actionable service links.
const e = $json.body ?? $json;
const severity = String(e.severity || '').toLowerCase();
const domain = String(e.domain || '').toLowerCase();
const source = e.source || 'unknown';

let tag = 'log';
let type = 'info';

if (domain === 'vault') {
  tag = 'vault';
  type = severity === 'page' ? 'failure' : 'info';
} else if (domain === 'deploy' || domain === 'deployment' || domain === 'gitops') {
  tag = 'deploy';
  type = severity === 'page' ? 'failure' : 'info';
} else if (domain === 'agent' || domain === 'agents' || domain === 'hermes') {
  tag = 'agent';
  type = severity === 'page' ? 'failure' : 'info';
} else if (severity === 'page' || severity === 'critical' || severity === 'error') {
  tag = 'page';
  type = 'failure';
} else {
  tag = 'log';
  type = 'info';
}

let emoji = '📋';
if (severity === 'page' || severity === 'critical' || severity === 'error') {
  emoji = '🚨';
} else if (domain === 'vault') {
  emoji = '🧠';
} else if (domain === 'deploy' || domain === 'deployment' || domain === 'gitops') {
  emoji = '🚀';
} else if (domain === 'agent' || domain === 'agents' || domain === 'hermes') {
  emoji = '🤖';
} else if (severity === 'warning' || severity === 'warn') {
  emoji = '⚠️';
}

let rawTitle = e.title || `[${source}] ${severity || 'event'}`;
rawTitle = rawTitle.replace(/^(:[a-z0-9_+-]+:|[🚨🧠🚀🤖⚠️📋ℹ️🔴🟡🟢])\s*/i, '').trim();
const formattedTitle = `${emoji} ${rawTitle}`;

let actionLink = '';
if (e.url) {
  actionLink = `\n👉 <${e.url}|${e.url_title || 'Abrir Servicio'}>`;
} else if (domain === 'vault') {
  actionLink = '\n👉 <https://github.com/mlorentedev/knowledge/issues|Ver Issues del Vault>';
} else if (source.includes('uptime-kuma') || source.includes('kuma')) {
  actionLink = '\n👉 <https://status.kubelab.live|Abrir Uptime Kuma>';
} else if (source.includes('grafana') || domain === 'monitoring') {
  actionLink = '\n👉 <https://grafana.kubelab.live|Abrir en Grafana>';
} else if (domain === 'deploy' || source.includes('argocd')) {
  actionLink = '\n👉 <https://argocd.kubelab.live|Abrir en Argo CD>';
}

let cleanBody = e.body || '';
cleanBody = cleanBody.replace(/^(:[a-z0-9_+-]+:|[🚨🧠🚀🤖⚠️📋ℹ️🔴🟡🟢])\s*/i, '').trim();
if (actionLink) {
  cleanBody = `${cleanBody}${actionLink}`;
}

return [{ json: {
  tag: tag,
  type: type,
  title: formattedTitle,
  body: cleanBody,
} }];
